/* Shapes identify roles independently of charge colour. All marks use world projection. */
static void draw_aircraft_weapons(void){for(int i=0;i<MAXE;i++){Obj*o=g.enemies+i;if(!o->on||o->ice83.frozen||!aircraft_weapon_role(o->type)||!enemy_damageable(o))continue;float x=o->x/(float)Q,y=o->y/(float)Q;int c=o->weaponClock%enemy_strength_interval(o,160),r=o->type==25?80:255,gg=o->type==27?80:190,bb=o->type==25?255:70;
 if(o->type==27){journey_line(x-4,y-24,x-4,y-17,r,gg,bb,220);journey_line(x+4,y-24,x+4,y-17,r,gg,bb,220);}else if(o->type==28){journey_line(x-6,y-22,x,y-16,r,gg,bb,220);journey_line(x,y-16,x+6,y-22,r,gg,bb,220);}else if(o->type==16){journey_line(x,y-25,x+5,y-20,r,gg,bb,220);journey_line(x+5,y-20,x,y-15,r,gg,bb,220);journey_line(x,y-15,x-5,y-20,r,gg,bb,220);journey_line(x-5,y-20,x,y-25,r,gg,bb,220);}else{journey_line(x-5,y-25,x+3,y-21,r,gg,bb,220);journey_line(x+3,y-21,x-3,y-18,r,gg,bb,220);journey_line(x-3,y-18,x+5,y-14,r,gg,bb,220);}
 if(c<1||c>=54)continue;if(o->type==27){float xx,yy;aircraft_beam_end(o,&xx,&yy);journey_line(x,y,xx,yy,255,80,150,c<40?85:220);if(c>=40){nquad=0;beam_ribbon(x,y,xx,yy,3,(SDL_FColor){1,.1f,.4f,.5f});beam_ribbon(x,y,xx,yy,.7f,(SDL_FColor){1,.85f,.9f,1});flush(halo);}}
 else if(c<40){float tx=o->aimX/(float)Q,ty=o->aimY/(float)Q;journey_line(x,y,tx,ty,r,gg,bb,45);for(int n=0;n<8;n++){float a=n*PI/4,b=(n+1)*PI/4,rad=o->type==16?24:9;journey_line(tx+cosf(a)*rad,ty+sinf(a)*rad,tx+cosf(b)*rad,ty+sinf(b)*rad,r,gg,bb,140);}journey_line(x-8,y+10,x-8+c*.4f,y+10,r,gg,bb,220);}}
 for(int i=0;i<MAXB;i++){Obj*o=g.bullets+i;if(!o->on||o->type<7||o->type>9)continue;float x=o->x/(float)Q,y=o->y/(float)Q;if(o->type==8){float tx=o->aimX/(float)Q,ty=o->aimY/(float)Q,rad=32;for(int n=0;n<16;n++){float a=n*PI/8,b=(n+1)*PI/8;journey_line(tx+cosf(a)*rad,ty+sinf(a)*rad,tx+cosf(b)*rad,ty+sinf(b)*rad,255,170,60,o->age>=60?190:75);}journey_line(x-5,y-6,x+5,y+6,255,200,60,230);}else if(o->type==9){for(int n=0;n<4;n++){float a=n*PI/2+visualTick*.08f;journey_line(x,y,x+cosf(a)*8,y+sinf(a)*8,110,190,255,230);}}else journey_line(x,y,x-o->vx*.018f,y-o->vy*.018f,255,195,60,230);}}
